"  const getPointsValueRate = () => {
    // Each point is worth points_to_amount_ratio directly in currency (e.g. 0.1 means 1 point = 0.1 currency units)
    const ratioSetting = getLoyaltySetting('points_to_amount_ratio', null);
    if (ratioSetting !== null && ratioSetting !== undefined) {
      return parseFloat(ratioSetting) || 0.1;
    }
    return 0.1; // Default: 1 point = 0.10
  };"

