"  const getPointsValueRate = () => {
    // Server uses: discount = points / points_to_amount_ratio
    // So 1 point = 1/ratio in currency. E.g. ratio=10 means 1pt = 0.10
    const ratioSetting = getLoyaltySetting('points_to_amount_ratio', null);
    if (ratioSetting !== null && ratioSetting !== undefined) {
      const ratio = parseFloat(ratioSetting);
      if (ratio && ratio > 0) return 1 / ratio;
    }
    return 0.1; // Default: 1 point = 0.10
  };"
